const [count, setCount] = useState(0);
function addTwice() {
  setCount(previous => previous + 1);
  setCount(previous => previous + 1);
}

// In a handler created when count is 0
setCount(count + 1);
console.log(count);

// React 18+ with createRoot; a timeout callback closes over count = 0
setTimeout(() => {
  setCount(count + 1);
  setCount(count + 1);
}, 0);
